            y = x + 1; nd = dx + (ch != 'R')
            if nd < dist[y]:
                dist[y] = nd
                if nd == dx: pushl(y)
                else: push(y)
        if c > 0:
            y = x - 1; nd = dx + (ch != 'L')
            if nd < dist[y]:
                dist[y] = nd
